\timing off
INSERT INTO accounts (id, name, subdomain, created_at, updated_at) VALUES
 (1, 'Acme', 'acme', now(), now()), (2, 'Other', 'other', now(), now());
SELECT setval('accounts_id_seq', 10);

-- 200k people in acme (mostly customers), 200k in another business, plus 5 staff in acme.
INSERT INTO users (id, account_id, name, email, password_digest, role, verified, suspended, created_at, updated_at)
SELECT g, CASE WHEN g <= 200000 THEN 1 ELSE 2 END, 'Person ' || g,
       'p' || g || '@example.test', 'x', 'customer', true, false, now(), now()
FROM generate_series(1, 400000) g;
INSERT INTO users (id, account_id, name, email, password_digest, role, verified, suspended, created_at, updated_at)
SELECT 400000 + g, 1, 'Staff ' || g, 'staff' || g || '@acme.test', 'x', CASE WHEN g = 1 THEN 'admin' ELSE 'agent' END, true, false, now(), now()
FROM generate_series(1, 5) g;
SELECT setval('users_id_seq', 500000);

-- 300k tickets for acme, updated at spread over ~2 years with some exact ties.
INSERT INTO tickets (id, account_id, requester_id, subject, status, created_at, updated_at, assignee_id, priority, source, reply_token, group_id)
SELECT g, 1,
       1 + (g * 7919) % 200000,
       'Ticket subject ' || g,
       (ARRAY['open','pending','solved','closed'])[1 + (g % 4)],
       now() - (g || ' seconds')::interval,
       TIMESTAMP '2026-11-19' - ((g * 37) % 63000000 || ' microseconds')::interval,
       NULL, 'normal', 'portal', md5(g::text), NULL
FROM generate_series(1, 300000) g;
SELECT setval('tickets_id_seq', 400000);

-- ~2 comments per ticket, plus 20k extra on one hot ticket (id 1) for the comments list.
INSERT INTO comments (ticket_id, author_id, body, public, created_at, updated_at)
SELECT 1 + (g % 300000), 1 + (g % 200000), 'Comment body ' || g, (g % 5) <> 0,
       TIMESTAMP '2026-01-01' + (g || ' seconds')::interval, now()
FROM generate_series(1, 600000) g;
INSERT INTO comments (ticket_id, author_id, body, public, created_at, updated_at)
SELECT 1, 400001, 'Hot ticket comment ' || g, true,
       TIMESTAMP '2026-01-01' + (g || ' seconds')::interval, now()
FROM generate_series(1, 20000) g;

INSERT INTO groups (id, account_id, name, created_at, updated_at)
SELECT g, 1, 'Group ' || g, now(), now() FROM generate_series(1, 20) g;
SELECT setval('groups_id_seq', 100);

INSERT INTO group_memberships (id, account_id, group_id, user_id, "default", created_at, updated_at)
SELECT g, 1, 1 + (g % 20), 400000 + 1 + (g % 5), false, now(), now() FROM generate_series(1, 2000) g;
SELECT setval('group_memberships_id_seq', 5000);

INSERT INTO invitations (id, account_id, email, role, token_digest, expires_at, sent_at, created_at, updated_at)
SELECT g, 1, 'inv' || g || '@example.test', 'agent', md5('inv' || g), now() + interval '7 days', now(), now(), now()
FROM generate_series(1, 50000) g;
SELECT setval('invitations_id_seq', 60000);
ANALYZE;
EOF
